"""Generate CloudFormation target. This script never connects to AWS."""
import json
from pathlib import Path
R = {}
ref=lambda x:{'Ref':x}
sub=lambda x:{'Fn::Sub':x}
att=lambda x,a='Arn':{'Fn::GetAtt':[x,a]}
def resource(name,typ,props,why,must=(),retain=False,**extra):
    r={'Type':typ,'Metadata':{'com.aws.cloudformation.Context':{'why':why,'must':list(must)}},'Properties':props,**extra}
    if retain:r.update(DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
    R[name]=r
def trust(service,conditions=None):
    s={'Effect':'Allow','Principal':{'Service':service},'Action':'sts:AssumeRole'}
    if conditions:s['Condition']=conditions
    return {'Version':'2012-10-17','Statement':[s]}
def allow(actions,resources,**extra):return dict(Effect='Allow',Action=actions,Resource=resources,**extra)
def policy(statements):return {'Version':'2012-10-17','Statement':statements}

resource('VaultKey','AWS::KMS::Key',{'EnableKeyRotation':True,'KeyPolicy':policy([{'Effect':'Allow','Principal':{'AWS':sub('arn:${AWS::Partition}:iam::${AWS::AccountId}:root')},'Action':'kms:*','Resource':'*'}])},'Envelope encryption of delegated user refresh tokens; root policy permits IAM delegation.',['No plaintext refresh tokens in table or logs'],True)
for name in ['Workspace','Audit']:
    p={'PublicAccessBlockConfiguration':dict(BlockPublicAcls=True,IgnorePublicAcls=True,BlockPublicPolicy=True,RestrictPublicBuckets=True),'OwnershipControls':{'Rules':[{'ObjectOwnership':'BucketOwnerEnforced'}]},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'VersioningConfiguration':{'Status':'Enabled'}}
    if name=='Workspace':p['LifecycleConfiguration']={'Rules':[{'Id':'ExpireOldVersions','Status':'Enabled','NoncurrentVersionExpiration':{'NoncurrentDays':30}},{'Id':'AbortIncomplete','Status':'Enabled','AbortIncompleteMultipartUpload':{'DaysAfterInitiation':1}}]}
    else:
        p['ObjectLockEnabled']=True
        p['ObjectLockConfiguration']={'ObjectLockEnabled':'Enabled','Rule':{'DefaultRetention':{'Mode':'COMPLIANCE','Days':366}}}
    resource(name,'AWS::S3::Bucket',p,'Private user files' if name=='Workspace' else 'Immutable audit objects retained >=12 months',['Block public access; TLS only; retain data on stack deletion'],True)
    resource(name+'Policy','AWS::S3::BucketPolicy',{'Bucket':ref(name),'PolicyDocument':policy([{'Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[att(name),sub('${'+name+'.Arn}/*')],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}])},'Deny unencrypted transport for all clients',['No public access grant'])
resource('State','AWS::DynamoDB::Table',{'BillingMode':'PAY_PER_REQUEST','AttributeDefinitions':[{'AttributeName':'pk','AttributeType':'S'},{'AttributeName':'sk','AttributeType':'S'}],'KeySchema':[{'AttributeName':'pk','KeyType':'HASH'},{'AttributeName':'sk','KeyType':'RANGE'}],'SSESpecification':{'SSEEnabled':True},'PointInTimeRecoverySpecification':{'PointInTimeRecoveryEnabled':True},'TimeToLiveSpecification':{'AttributeName':'expires_at','Enabled':True},'DeletionProtectionEnabled':True},'Key-based chat metadata, approvals, ACL snapshots, quota reservations and encrypted vault; managed multi-AZ.',['Application must verify expiry; TTL deletion is asynchronous','pk derived from authenticated identity; never trust tenant in request body'],True)
resource('Vectors','AWS::S3Vectors::VectorBucket',{},'Pay-per-use vector persistence instead of an always-running search cluster.',['All queries pass server authorization; no direct client access'],True)
resource('KnowledgeIndex','AWS::S3Vectors::Index',{'VectorBucketArn':ref('Vectors'),'DataType':'float32','Dimension':1024,'DistanceMetric':'cosine'},'Custom retrieval with ACL filters and live source ACL recheck, not a managed full-tenant crawler.',['Embedding dimension must match; no retrieved text goes to model until ACL recheck'],True)
resource('DeadLetters','AWS::SQS::Queue',{'SqsManagedSseEnabled':True,'MessageRetentionPeriod':1209600},'Quarantine poison async work.',['No OAuth tokens or PII in queue body'])
resource('Jobs','AWS::SQS::Queue',{'SqsManagedSseEnabled':True,'VisibilityTimeout':3600,'MessageRetentionPeriod':86400,'RedrivePolicy':{'deadLetterTargetArn':att('DeadLetters'),'maxReceiveCount':3}},'Async background jobs carry only authorized object/job pointers.',['Idempotent consumers; explicit external-write approval; 10-minute job deadline'])
resource('QueuePolicy','AWS::SQS::QueuePolicy',{'Queues':[ref('Jobs'),ref('DeadLetters')],'PolicyDocument':policy([{'Effect':'Deny','Principal':'*','Action':'sqs:*','Resource':[att('Jobs'),att('DeadLetters')],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}])},'Require TLS for queue access.')
resource('SandboxVpc','AWS::EC2::VPC',{'CidrBlock':'10.88.0.0/24','EnableDnsSupport':False,'EnableDnsHostnames':False},'Dedicated sandbox network with no IGW, NAT, peering, endpoints or DNS resolver.',['Never attach corporate/private resources or outbound routes','Disabling VPC DNS closes the resolver path that security groups do not filter'])
for n,cidr,az in [('A','10.88.0.0/26',0),('B','10.88.0.64/26',1)]:
    resource('SandboxSubnet'+n,'AWS::EC2::Subnet',{'VpcId':ref('SandboxVpc'),'CidrBlock':cidr,'AvailabilityZone':{'Fn::Select':[az,{'Fn::GetAZs':''}]},'MapPublicIpOnLaunch':False},'Isolated subnet in an independent AZ.',['Local-only routes'])
resource('SandboxGroup','AWS::EC2::SecurityGroup',{'GroupDescription':'No ingress; egress only to nonexistent localhost destination','VpcId':ref('SandboxVpc'),'SecurityGroupEgress':[{'IpProtocol':'-1','CidrIp':'127.0.0.1/32','Description':'Explicit inert rule prevents AWS default allow-all egress'}]},'Block outbound paths by default; do not use the permissive default SG.',['No usable egress; no DNS via Amazon resolver'])
resource('Interpreter','AWS::BedrockAgentCore::CodeInterpreterCustom',{'Name':sub('vbot_${Environment}_interpreter'),'NetworkConfiguration':{'NetworkMode':'VPC','VpcConfig':{'Subnets':[ref('SandboxSubnetA'),ref('SandboxSubnetB')],'SecurityGroups':[ref('SandboxGroup')]}}},'Per-job isolated code session; controller uploads/downloads files over AgentCore tools.',['No execution role exposing OAuth, database or user-bucket access','Controller stops session in finally, sets timeout <=600s and checks ownership'])
resource('UserPool','AWS::Cognito::UserPool',{'UserPoolName':sub('${AWS::StackName}-users'),'UserPoolTier':'ESSENTIALS','AdminCreateUserConfig':{'AllowAdminCreateUserOnly':True},'Schema':[{'Name':'email','AttributeDataType':'String','Mutable':True,'Required':True}],'DeletionProtection':'ACTIVE'},'Enterprise SSO federation; MFA must be enforced at corporate IdP.',['Local password signup disabled; validate IdP MFA policy'],True)
resource('CorporateIdP','AWS::Cognito::UserPoolIdentityProvider',{'UserPoolId':ref('UserPool'),'ProviderName':'Corporate','ProviderType':'SAML','ProviderDetails':{'MetadataURL':ref('SamlMetadataUrl')},'AttributeMapping':{'email':'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress'}},'Federate SAML enterprise identity; metadata must map stable subject and MFA.',['Metadata URL belongs to approved corporate IdP'])
resource('ApiScopes','AWS::Cognito::UserPoolResourceServer',{'UserPoolId':ref('UserPool'),'Identifier':'vbot','Name':'vbot','Scopes':[{'ScopeName':'chat','ScopeDescription':'Access workplace assistant'}]},'Require access tokens carrying a scoped API permission.')
resource('Client','AWS::Cognito::UserPoolClient',{'UserPoolId':ref('UserPool'),'GenerateSecret':False,'AllowedOAuthFlowsUserPoolClient':True,'AllowedOAuthFlows':['code'],'AllowedOAuthScopes':['openid','email','vbot/chat'],'SupportedIdentityProviders':['Corporate'],'CallbackURLs':[ref('CallbackUrl')],'EnableTokenRevocation':True,'PreventUserExistenceErrors':'ENABLED','AccessTokenValidity':15,'TokenValidityUnits':{'AccessToken':'minutes'}},'Browser OAuth authorization-code flow with PKCE.',['Frontend must supply PKCE S256; exact HTTPS callback only'],DependsOn=['CorporateIdP','ApiScopes'])
resource('LoginDomain','AWS::Cognito::UserPoolDomain',{'UserPoolId':ref('UserPool'),'Domain':sub('${AWS::AccountId}-${AWS::StackName}')},'Managed SSO redirect endpoint.')
for group in ['ChatLogs','WorkerLogs']:
    resource(group,'AWS::Logs::LogGroup',{'RetentionInDays':30},'Operational metadata only; immutable audit events go to S3.',['Never log raw prompt, document, OAuth token or secret'])
common=[allow(['dynamodb:GetItem','dynamodb:PutItem','dynamodb:UpdateItem','dynamodb:Query','dynamodb:ConditionCheckItem'],att('State')),allow(['s3:GetObject','s3:PutObject'],sub('${Workspace.Arn}/*')),allow('s3:PutObject',sub('${Audit.Arn}/*')),allow(['kms:Encrypt','kms:Decrypt','kms:GenerateDataKey'],att('VaultKey')),allow(['s3vectors:QueryVectors','s3vectors:GetVectors','s3vectors:PutVectors','s3vectors:DeleteVectors'],att('KnowledgeIndex','IndexArn'))]
for name,logs in [('ChatRole','ChatLogs'),('WorkerRole','WorkerLogs')]:
    statements=common+[allow(['logs:CreateLogStream','logs:PutLogEvents'],att(logs))]
    statements += [allow(['bedrock:InvokeModel','bedrock:InvokeModelWithResponseStream'],[sub('arn:${AWS::Partition}:bedrock:*::foundation-model/amazon.nova-lite-v1:0'),sub('arn:${AWS::Partition}:bedrock:*::foundation-model/amazon.nova-canvas-v1:0'),sub('arn:${AWS::Partition}:bedrock:*::foundation-model/amazon.titan-embed-text-v2:0'),sub('arn:${AWS::Partition}:bedrock:*::foundation-model/anthropic.claude-sonnet-4-5-20250929-v1:0'),sub('arn:${AWS::Partition}:bedrock:${AWS::Region}:${AWS::AccountId}:inference-profile/us.*')],Condition={'StringEquals':{'aws:RequestedRegion':['us-east-1','us-east-2','us-west-2']}})]
    if name=='ChatRole':statements+=[allow('sqs:SendMessage',att('Jobs'))]
    else:statements += [allow(['sqs:ReceiveMessage','sqs:DeleteMessage','sqs:GetQueueAttributes','sqs:ChangeMessageVisibility'],att('Jobs')),allow(['bedrock-agentcore:StartCodeInterpreterSession','bedrock-agentcore:InvokeCodeInterpreter','bedrock-agentcore:StopCodeInterpreterSession','bedrock-agentcore:GetCodeInterpreterSession'],att('Interpreter','CodeInterpreterArn')),allow('secretsmanager:GetSecretValue',ref('ConnectorSecretArns'))]
    resource(name,'AWS::IAM::Role',{'AssumeRolePolicyDocument':trust('lambda.amazonaws.com'),'Policies':[{'PolicyName':'RuntimeResources','PolicyDocument':policy(statements)}]},'Separate trusted runtime role; resource-scoped capabilities.',['No role or credentials passed into untrusted sandbox','Cross-region Bedrock limited to US destination regions; model allowlist in application'])
for name,role,log,key,timeout,conc in [('Chat','ChatRole','ChatLogs','ChatCodeKey',120,100),('Worker','WorkerRole','WorkerLogs','WorkerCodeKey',600,20)]:
    env={'STATE_TABLE':ref('State'),'WORKSPACE_BUCKET':ref('Workspace'),'AUDIT_BUCKET':ref('Audit'),'VAULT_KEY_ID':ref('VaultKey'),'VECTOR_INDEX_ARN':att('KnowledgeIndex','IndexArn'),'JOB_QUEUE_URL':ref('Jobs'),'INTERPRETER_ID':att('Interpreter','CodeInterpreterId'),'MAX_JOB_SECONDS':'600','MAX_USER_STORAGE_BYTES':'10000000000','DAILY_USER_TASK_LIMIT':'16','MONTHLY_MODEL_BUDGET_USD':'4500','RELEASE_ENABLED':'false'}
    resource(name,'AWS::Lambda::Function',{'Runtime':'nodejs22.x','Architectures':['arm64'],'Handler':'index.handler','MemorySize':512 if name=='Chat' else 1024,'Timeout':timeout,'ReservedConcurrentExecutions':conc,'Role':att(role),'Code':{'S3Bucket':ref('CodeBucket'),'S3Key':ref(key)},'LoggingConfig':{'LogGroup':ref(log)},'Environment':{'Variables':env}},'Deploy reviewed application artifact supplied separately; release disabled until gates pass.',['No inline placeholder business logic','Streaming chat uses awslambda.streamifyResponse; workers enforce deadline and idempotency'])
resource('WorkerEvents','AWS::Lambda::EventSourceMapping',{'EventSourceArn':att('Jobs'),'FunctionName':ref('Worker'),'BatchSize':1,'FunctionResponseTypes':['ReportBatchItemFailures'],'ScalingConfig':{'MaximumConcurrency':10}},'Bound background concurrency and preserve per-job deadline.')
resource('ChatVersion','AWS::Lambda::Version',{'FunctionName':ref('Chat'),'CodeSha256':ref('ChatCodeSha256')},'Immutable build version pinned to uploaded ZIP digest.')
resource('Live','AWS::Lambda::Alias',{'Name':'live','FunctionName':ref('Chat'),'FunctionVersion':att('ChatVersion','Version')},'Stable integration alias for controlled releases.')
resource('ScaleRole','AWS::IAM::Role',{'AssumeRolePolicyDocument':trust('application-autoscaling.amazonaws.com'),'Policies':[{'PolicyName':'WarmAlias','PolicyDocument':policy([allow(['lambda:PutProvisionedConcurrencyConfig','lambda:DeleteProvisionedConcurrencyConfig','lambda:GetProvisionedConcurrencyConfig'],ref('Live'))])}]},'Only schedule warm capacity on the chat alias.')
resource('WarmCapacity','AWS::ApplicationAutoScaling::ScalableTarget',{'MinCapacity':0,'MaxCapacity':10,'ResourceId':sub('function:${Chat}:live'),'RoleARN':att('ScaleRole'),'ScalableDimension':'lambda:function:ProvisionedConcurrency','ServiceNamespace':'lambda','ScheduledActions':[{'ScheduledActionName':'BusinessStart','Schedule':'cron(50 0 ? * MON-FRI *)','ScalableTargetAction':{'MinCapacity':10,'MaxCapacity':10}},{'ScheduledActionName':'BusinessEnd','Schedule':'cron(0 11 ? * MON-FRI *)','ScalableTargetAction':{'MinCapacity':0,'MaxCapacity':0}}]},'Warm 10 slots before 08:00 GMT+7; off after 18:00. Ten extra warm-up minutes priced as contingency.',Condition='IsProd')
resource('Api','AWS::ApiGateway::RestApi',{'Name':sub('${AWS::StackName}-api'),'EndpointConfiguration':{'Types':['REGIONAL']}},'Managed multi-AZ TLS gateway and load distribution; REST required for streaming.',['Do not replace with HTTP API without proving streaming path'])
resource('Authorizer','AWS::ApiGateway::Authorizer',{'Name':'Cognito','Type':'COGNITO_USER_POOLS','RestApiId':ref('Api'),'IdentitySource':'method.request.header.Authorization','ProviderARNs':[att('UserPool')]},'Validate SSO access tokens before application execution.')
resource('ChatPath','AWS::ApiGateway::Resource',{'RestApiId':ref('Api'),'ParentId':att('Api','RootResourceId'),'PathPart':'chat'},'Streaming chat endpoint.')
resource('ChatMethod','AWS::ApiGateway::Method',{'RestApiId':ref('Api'),'ResourceId':ref('ChatPath'),'HttpMethod':'POST','AuthorizationType':'COGNITO_USER_POOLS','AuthorizerId':ref('Authorizer'),'AuthorizationScopes':['vbot/chat'],'Integration':{'Type':'AWS_PROXY','IntegrationHttpMethod':'POST','ResponseTransferMode':'STREAM','TimeoutInMillis':120000,'Uri':sub('arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2021-11-15/functions/${Live}/response-streaming-invocations')}},'Stream model output through the managed gateway.',['Guardrail streamed text before emitting chunks; no sensitive prefix leak'])
resource('InvokePermission','AWS::Lambda::Permission',{'FunctionName':ref('Live'),'Action':'lambda:InvokeFunction','Principal':'apigateway.amazonaws.com','SourceAccount':ref('AWS::AccountId'),'SourceArn':sub('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${Api}/*/POST/chat')},'Only this API can invoke the alias.')
resource('Deployment','AWS::ApiGateway::Deployment',{'RestApiId':ref('Api')},'Immutable gateway deployment; logical ID must change when methods change.',DependsOn=['ChatMethod'])
resource('Stage','AWS::ApiGateway::Stage',{'RestApiId':ref('Api'),'DeploymentId':ref('Deployment'),'StageName':ref('Environment'),'MethodSettings':[{'HttpMethod':'*','ResourcePath':'/*','ThrottlingRateLimit':5,'ThrottlingBurstLimit':20,'DataTraceEnabled':False}]},'Bound external traffic; application still enforces per-user budget.',['No request body data tracing'])
resource('Firewall','AWS::WAFv2::WebACL',{'Scope':'REGIONAL','DefaultAction':{'Allow':{}},'VisibilityConfig':{'SampledRequestsEnabled':False,'CloudWatchMetricsEnabled':True,'MetricName':'VBotWaf'},'Rules':[{'Name':'IpRate','Priority':0,'Action':{'Block':{}},'Statement':{'RateBasedStatement':{'Limit':300,'AggregateKeyType':'IP'}},'VisibilityConfig':{'SampledRequestsEnabled':False,'CloudWatchMetricsEnabled':True,'MetricName':'IpRate'}}]},'Rate-limit abusive clients without storing sampled sensitive requests.')
resource('FirewallBinding','AWS::WAFv2::WebACLAssociation',{'WebACLArn':att('Firewall'),'ResourceArn':sub('arn:${AWS::Partition}:apigateway:${AWS::Region}::/restapis/${Api}/stages/${Environment}')},'Attach the regional WAF directly to the gateway.',DependsOn=['Stage'])
resource('Budget','AWS::Budgets::Budget',{'Budget':{'BudgetName':sub('${AWS::StackName}-monthly'),'BudgetType':'COST','TimeUnit':'MONTHLY','BudgetLimit':{'Amount':6500,'Unit':'USD'},'CostFilters':{'TagKeyValue':[sub('user:Project$${AWS::StackName}')]}},'NotificationsWithSubscribers':[{'Notification':{'NotificationType':'ACTUAL','ComparisonOperator':'GREATER_THAN','Threshold':threshold,'ThresholdType':'PERCENTAGE'},'Subscribers':[{'SubscriptionType':'EMAIL','Address':ref('BudgetEmail')}]} for threshold in [80,100]]},'Advisory tagged cost budget; hard cutoff must be enforced by request ledger.',['Activate Project cost allocation tag; budget is delayed and is not an immediate spending cap'])

params={
 'Environment':{'Type':'String','AllowedValues':['prod','staging'],'Default':'staging'},
 'BudgetEmail':{'Type':'String','AllowedPattern':'[^@ ]+@[^@ ]+\\.[^@ ]+'},
 'SamlMetadataUrl':{'Type':'String','AllowedPattern':'https://.+'},
 'CallbackUrl':{'Type':'String','AllowedPattern':'https://.+'},
 'CodeBucket':{'Type':'String','AllowedPattern':'[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]'},
 'ChatCodeKey':{'Type':'String','AllowedPattern':'.+\\.zip'},
 'WorkerCodeKey':{'Type':'String','AllowedPattern':'.+\\.zip'},
 'ChatCodeSha256':{'Type':'String','AllowedPattern':'[A-Za-z0-9+/]{43}='},
 'ConnectorSecretArns':{'Type':'CommaDelimitedList','Description':'Existing application OAuth client secret ARNs; never provide secret values.'}
}
# Tags are uniform for supported resource types. Some API Gateway child types have no tags.
tag_types={'AWS::S3::Bucket','AWS::DynamoDB::Table','AWS::SQS::Queue','AWS::EC2::VPC','AWS::EC2::Subnet','AWS::EC2::SecurityGroup','AWS::IAM::Role','AWS::Lambda::Function','AWS::Logs::LogGroup','AWS::WAFv2::WebACL','AWS::S3Vectors::VectorBucket','AWS::S3Vectors::Index'}
for r in R.values():
    if r['Type'] in tag_types:r['Properties']['Tags']=[{'Key':'Project','Value':ref('AWS::StackName')},{'Key':'Environment','Value':ref('Environment')}]
template={'AWSTemplateFormatVersion':'2010-09-09','Description':'VBot AWS target: multi-AZ managed API, serverless state, pay-per-use inference and isolated per-job code interpreter. Application artifacts and release validation required.','Metadata':{'AWSToolsMetrics':{'AWSAgentToolkit':'aws-cloudformation@3'},'com.aws.cloudformation.Context':{'arch':'Trusted Lambda control plane outside VPC; untrusted Code Interpreter inside isolated VPC.','must':['No live deploy authorized in this design phase','SSO, ACL, budget and model quality gates before release'],'ref':['../docs/ARCHITECTURE.md','../docs/DEPLOYMENT.md']}},'Parameters':params,'Conditions':{'IsProd':{'Fn::Equals':[ref('Environment'),'prod']}},'Resources':R,'Outputs':{'ApiUrl':{'Description':'Authenticated streaming endpoint','Value':sub('https://${Api}.execute-api.${AWS::Region}.${AWS::URLSuffix}/${Environment}/chat')},'ClientId':{'Description':'Public PKCE client','Value':ref('Client')},'WorkspaceBucket':{'Description':'Private file store','Value':ref('Workspace')},'StateTable':{'Description':'Key-based application state','Value':ref('State')},'InterpreterId':{'Description':'Controller starts fresh per-job session here','Value':att('Interpreter','CodeInterpreterId')}}}
out=Path(__file__).resolve().parents[1]/'infra'/'vbot.template.json'
out.write_text(json.dumps(template,indent=1)+'\n',encoding='utf-8')
print(f'{len(R)} resources; {out.stat().st_size} bytes; no AWS calls')
